const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('.desktop-nav');toggle?.addEventListener('click',()=>{nav?.classList.toggle('mobile-open')});document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>nav?.classList.remove('mobile-open')));
document.querySelectorAll('.faq-list details').forEach(d=>d.addEventListener('toggle',()=>{const i=d.querySelector('.faq-icon');if(i)i.textContent=d.open?'−':'+'}));
const whatsappUrl='https://wa.me/5531994504868?text=Ol%C3%A1,%20tudo%20bem?%20Preciso%20de%20ajuda%20com%20a%20minha%20empresa%20de%20transporte%20de%20passageiros.';document.querySelectorAll('.site-cta,.btn,.service-card a').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();window.open(whatsappUrl,'_blank','noopener')}));
document.addEventListener('DOMContentLoaded',()=>{const items=document.querySelectorAll('.text-scroll-anim');if(window.SplitType){items.forEach(el=>{new SplitType(el,{types:'words'});const obs=new IntersectionObserver(entries=>entries.forEach(entry=>{entry.target.classList.toggle('is-visible',entry.isIntersecting)}),{threshold:.35});obs.observe(el)})}});
